<template>
  <Popover placement="bottom-end">
    <template #target="{ togglePopover, close }">
      <div class="flex items-center w-fit">
        <Button
          :label="__('Filter')"
          :class="filters?.size ? 'rounded-e-none' : ''"
          @click="togglePopover"
        >
          <template #prefix><FilterIcon class="h-4" /></template>
          <template v-if="filters?.size" #suffix>
            <span
              class="flex h-5 w-5 items-center justify-center rounded-[5px] bg-surface-white pt-px text-xs font-medium text-ink-gray-8 shadow-sm"
            >
              {{ filters.size }}
            </span>
          </template>
        </Button>
        <!-- //// Neoffice — wrapped in __(): upstream showed this string in English on every non-English site -->
        <Tooltip v-if="filters?.size" :text="__('Clear all Filter')">
          <div>
            <Button
              class="rounded-s-none border-s"
              icon="x"
              @click.stop="clearfilter(close)"
            />
          </div>
        </Tooltip>
      </div>
    </template>
    <template #body="{ close }">
      <div
        class="my-2 rounded-lg border border-outline-gray-1 bg-surface-white shadow-xl"
      >
        <div class="min-w-72 p-2 sm:min-w-[400px]">
          <div
            v-if="filters?.size"
            v-for="(f, i) in filters"
            :key="i"
            id="filter-list"
            class="mb-4 sm:mb-3"
          >
            <div v-if="isMobileView" class="flex flex-col gap-2">
              <div class="-mb-2 flex w-full items-center justify-between">
                <div class="text-base text-ink-gray-5">
                  {{ i == 0 ? "Where" : "And" }}
                </div>
                <Button
                  class="flex"
                  variant="ghost"
                  icon="x"
                  @click="removeFilter(i)"
                />
              </div>
              <div id="fieldname" class="w-full">
                <!-- //// Neoffice — wrapped in __(): upstream showed this string in English on every non-English site -->
                <Autocomplete
                  v-model="f.field.fieldname"
                  :options="filterableFields.data"
                  @update:modelValue="(e) => updateFilter(e, i)"
                  :placeholder="__('First Name')"
                />
              </div>
              <div id="operator">
                <!-- //// Neoffice — wrapped in __(): upstream showed this string in English on every non-English site -->
                <FormControl
                  type="select"
                  v-model="f.operator"
                  @change="(e) => updateOperator(e, f)"
                  :options="getOperators(f.field.fieldtype, f.field.fieldname)"
                  :placeholder="__('Equals')"
                />
              </div>
              <div id="value" class="w-full">
                <!-- //// Neoffice — wrapped in __(): upstream showed this string in English on every non-English site -->
                <component
                  :is="getValueControl(f)"
                  :model-value="f.value"
                  @update:modelValue="(v) => updateValue(v, f)"
                  @change="(v) => updateValue(v, f)"
                  :placeholder="__('John Doe')"
                />
              </div>
            </div>
            <div v-else class="flex items-center justify-between gap-2">
              <div class="flex items-center gap-2 flex-1">
                <div class="w-13 ps-2 text-end text-base text-ink-gray-5">
                  {{ i == 0 ? "Where" : "And" }}
                </div>
                <div id="fieldname" class="!min-w-[140px]">
                  <!-- //// Neoffice — wrapped in __(): upstream showed this string in English on every non-English site -->
                  <Autocomplete
                    v-model="f.field.fieldname"
                    :options="filterableFields.data"
                    @update:modelValue="(e) => updateFilter(e, i)"
                    :placeholder="__('First Name')"
                  />
                </div>
                <div id="operator">
                  <!-- //// Neoffice — wrapped in __(): upstream showed this string in English on every non-English site -->
                  <FormControl
                    type="select"
                    class="!min-w-[140px]"
                    v-model="f.operator"
                    @change="(e) => updateOperator(e, f)"
                    :options="
                      getOperators(f.field.fieldtype, f.field.fieldname)
                    "
                    :placeholder="__('Equals')"
                  />
                </div>
                <div id="value" class="!min-w-[140px] flex-1">
                  <!-- //// Neoffice — wrapped in __(): upstream showed this string in English on every non-English site -->
                  <component
                    :is="getValueControl(f)"
                    :model-value="f.value"
                    @change="(v) => updateValue(v, f)"
                    @update:modelValue="(v) => updateValue(v, f)"
                    :placeholder="__('John Doe')"
                  />
                </div>
              </div>
              <Button
                class="flex"
                variant="ghost"
                icon="x"
                @click="removeFilter(i)"
              />
            </div>
          </div>
          <div
            v-else
            class="mb-3 flex h-7 items-center px-3 text-sm text-ink-gray-5"
          >
            {{ __("Empty - Choose a field to filter by") }}
          </div>
          <div class="flex items-center justify-between gap-2">
            <!-- //// Neoffice — wrapped in __(): upstream showed this string in English on every non-English site -->
            <Autocomplete
              :options="filterableFields.data"
              @update:modelValue="(e) => setfilter(e)"
              :placeholder="__('First name')"
            >
              <template #target="{ togglePopover }">
                <Button
                  class="!text-ink-gray-5"
                  variant="ghost"
                  @click="togglePopover()"
                  :label="__('Add Filter')"
                >
                  <template #prefix>
                    <FeatherIcon name="plus" class="h-4" />
                  </template>
                </Button>
              </template>
            </Autocomplete>
            <!-- //// Neoffice — wrapped in __(): upstream showed this string in English on every non-English site -->
            <Button
              v-if="filters?.size"
              class="!text-ink-gray-5"
              variant="ghost"
              :label="__('Clear all Filter')"
              @click="clearfilter(close)"
            />
          </div>
        </div>
      </div>
    </template>
  </Popover>
</template>
<script setup>
import { Link, StarRating } from "@/components";
import FilterIcon from "@/components/icons/FilterIcon.vue";
import { useScreenSize } from "@/composables/screen";
import { useDebounceFn } from "@vueuse/core";
import {
  Button,
  Combobox,
  DatePicker,
  DateRangePicker,
  DateTimePicker,
  FeatherIcon,
  FormControl,
  Popover,
  Tooltip,
} from "frappe-ui";
import Autocomplete from "@/components/frappe-ui/Autocomplete.vue";
import { computed, h, inject } from "vue";
//// Neoffice — __ for the operator, value and timespan labels below, which upstream hardcoded in English.
import { __ } from "@/translation";

const props = defineProps({
  default_filters: {
    type: Object,
    required: false,
    default: {},
  },
});

const { isMobileView } = useScreenSize();

const typeCheck = ["Check"];
const typeLink = ["Link", "Dynamic Link"];
const typeNumber = ["Float", "Int", "Currency", "Percent"];
const typeSelect = ["Select"];
const typeString = ["Data", "Long Text", "Small Text", "Text Editor", "Text"];
const typeDate = ["Date", "Datetime"];
const typeRating = ["Rating"];

const listViewData = inject("listViewData");
const listViewActions = inject("listViewActions");
const { list, filterableFields } = listViewData;

const filters = computed(() => {
  if (!list) return new Set();
  let allFilters = list?.params?.filters || list.data?.params?.filters;
  if (!allFilters || !filterableFields.data) return new Set();

  return convertFilters(filterableFields.data, allFilters);
});

function convertFilters(data, allFilters) {
  let f = [];
  for (let [key, value] of Object.entries(allFilters)) {
    let field = data.find((f) => f.fieldname === key);
    if (typeof value !== "object" || !value) {
      value = ["=", value];
      if (field?.fieldtype === "Check") {
        value = ["equals", value[1] ? "Yes" : "No"];
      }
    }
    if (typeof value[1] === "number") {
      value[1] = value[1].toString();
    }
    if (field) {
      f.push({
        field,
        fieldname: key,
        operator: oppositeOperatorMap[value[0]],
        value: value[1],
      });
    }
  }
  return new Set(f);
}

//// Neoffice — operator labels wrapped in __() below: upstream showed them in English on every non-English site.
function getOperators(fieldtype, fieldname) {
  let options = [];
  if (typeString.includes(fieldtype)) {
    options.push(
      ...[
        { label: __('Equals'), value: "equals" }, //// Neoffice — __(), see getOperators()
        { label: __('Not Equals'), value: "not equals" },
        { label: __('Like'), value: "like" },
        { label: __('Not Like'), value: "not like" },
        { label: "In", value: "in" },
        { label: __('Not In'), value: "not in" }, //// Neoffice — __(), see getOperators()
        { label: "Is", value: "is" },
      ]
    );
  }
  if (fieldname === "_assign") {
    // TODO: make equals and not equals work
    options = [
      { label: __('Like'), value: "like" }, //// Neoffice — __(), see getOperators()
      { label: __('Not Like'), value: "not like" },
      { label: "Is", value: "is" },
    ];
  }
  if (typeNumber.includes(fieldtype)) {
    options.push(
      ...[
        { label: __('Equals'), value: "equals" }, //// Neoffice — __(), see getOperators()
        { label: __('Not Equals'), value: "not equals" },
        { label: __('Like'), value: "like" },
        { label: __('Not Like'), value: "not like" },
        { label: "In", value: "in" },
        { label: __('Not In'), value: "not in" }, //// Neoffice — __(), see getOperators()
        { label: "Is", value: "is" },
        { label: "<", value: "<" },
        { label: ">", value: ">" },
        { label: "<=", value: "<=" },
        { label: ">=", value: ">=" },
      ]
    );
  }
  if (typeSelect.includes(fieldtype)) {
    options.push(
      ...[
        { label: __('Equals'), value: "equals" }, //// Neoffice — __(), see getOperators()
        { label: __('Not Equals'), value: "not equals" },
        { label: "In", value: "in" },
        { label: __('Not In'), value: "not in" }, //// Neoffice — __(), see getOperators()
        { label: "Is", value: "is" },
      ]
    );
  }
  if (typeLink.includes(fieldtype)) {
    options.push(
      ...[
        { label: __('Equals'), value: "equals" }, //// Neoffice — __(), see getOperators()
        { label: __('Not Equals'), value: "not equals" },
        { label: __('Like'), value: "like" },
        { label: __('Not Like'), value: "not like" },
        { label: "In", value: "in" },
        { label: __('Not In'), value: "not in" }, //// Neoffice — __(), see getOperators()
        { label: "Is", value: "is" },
      ]
    );
  }
  if (typeCheck.includes(fieldtype)) {
    options.push(...[{ label: __('Equals'), value: "equals" }]); //// Neoffice — __(), see getOperators()
  }
  if (["Duration"].includes(fieldtype)) {
    options.push(
      ...[
        { label: __('Like'), value: "like" }, //// Neoffice — __(), see getOperators()
        { label: __('Not Like'), value: "not like" },
        { label: "In", value: "in" },
        { label: __('Not In'), value: "not in" }, //// Neoffice — __(), see getOperators()
        { label: "Is", value: "is" },
      ]
    );
  }
  if (typeDate.includes(fieldtype)) {
    options.push(
      ...[
        { label: __('Equals'), value: "equals" }, //// Neoffice — __(), see getOperators()
        { label: __('Not Equals'), value: "not equals" },
        { label: "Is", value: "is" },
        { label: ">", value: ">" },
        { label: "<", value: "<" },
        { label: ">=", value: ">=" },
        { label: "<=", value: "<=" },
        { label: __('Between'), value: "between" }, //// Neoffice — __(), see getOperators()
        { label: __('Timespan'), value: "timespan" },
      ]
    );
  }
  if (typeRating.includes(fieldtype)) {
    options.push(
      ...[
        { label: __('Equals'), value: "equals" }, //// Neoffice — __(), see getOperators()
        { label: __('Not Equals'), value: "not equals" },
        { label: "Is", value: "is" },
        { label: ">", value: ">" },
        { label: "<", value: "<" },
        { label: ">=", value: ">=" },
        { label: "<=", value: "<=" },
      ]
    );
  }
  return options;
}

function getValueControl(f) {
  const { field, operator } = f;
  const { fieldtype, options } = field;
  if (operator == "is") {
    return h(FormControl, {
      type: "select",
      options: [
        {
          label: __('Set'), //// Neoffice — __(), see getOperators()
          value: "set",
        },
        {
          label: __('Not Set'), //// Neoffice — __(), see getOperators()
          value: "not set",
        },
      ],
    });
  } else if (operator == "timespan") {
    return h(Combobox, {
      options: timespanOptions,
      trigger: "button",
      modelValue: f.value,
      "onUpdate:modelValue": (v) => updateValue(v, f),
    });
  } else if (["like", "not like", "in", "not in"].includes(operator)) {
    return h(FormControl, { type: "text" });
  } else if (typeSelect.includes(fieldtype) || typeCheck.includes(fieldtype)) {
    const _options =
      fieldtype == "Check" ? ["Yes", "No"] : getSelectOptions(options);
    return h(FormControl, {
      type: "select",
      options: _options.map((o) => ({
        label: o,
        value: o,
      })),
    });
  } else if (typeLink.includes(fieldtype)) {
    if (fieldtype == "Dynamic Link") {
      return h(FormControl, { type: "text" });
    }
    return h(Link, { class: "form-control", doctype: options, value: f.value });
  } else if (typeNumber.includes(fieldtype)) {
    return h(FormControl, { type: "number" });
  } else if (typeDate.includes(fieldtype) && operator == "between") {
    return h(DateRangePicker, { value: f.value, iconLeft: "" });
  } else if (typeDate.includes(fieldtype)) {
    return h(fieldtype == "Date" ? DatePicker : DateTimePicker, {
      value: f.value,
      iconLeft: "",
    });
  } else if (typeRating.includes(fieldtype)) {
    return h(StarRating, {
      rating: f.value || 0,
      static: false,
      class: "truncate",
      "onUpdate:modelValue": (v) => updateValue(v, f),
    });
  } else {
    return h(FormControl, { type: "text" });
  }
}

function getDefaultValue(field) {
  if (typeSelect.includes(field.fieldtype)) {
    return getSelectOptions(field.options)[0];
  }
  if (typeCheck.includes(field.fieldtype)) {
    return "Yes";
  }
  if (typeDate.includes(field.fieldtype)) {
    return null;
  }
  if (typeRating.includes(field.fieldtype)) {
    return 0;
  }
  return "";
}

function getDefaultOperator(fieldtype, fieldname = null) {
  if (fieldname === "_assign") {
    return "like";
  }
  if (typeSelect.includes(fieldtype)) {
    return "equals";
  }
  if (typeCheck.includes(fieldtype) || typeNumber.includes(fieldtype)) {
    return "equals";
  }
  if (typeDate.includes(fieldtype)) {
    return "between";
  }
  if (typeLink.includes(fieldtype)) {
    return "equals";
  }
  if (typeRating.includes(fieldtype)) {
    return "equals";
  }
  return "like";
}

function getSelectOptions(options) {
  return options.split("\n");
}

function setfilter(data) {
  if (!data) return;
  filters.value.add({
    field: {
      label: data.label,
      fieldname: data.value,
      fieldtype: data.fieldtype,
      options: data.options,
    },
    fieldname: data.value,
    operator: getDefaultOperator(data.fieldtype, data.fieldname),
    value: getDefaultValue(data),
  });
  apply();
}

function updateFilter(data, index) {
  filters.value.delete(Array.from(filters.value)[index]);
  filters.value.add({
    fieldname: data.value,
    operator: getDefaultOperator(data.fieldtype),
    value: getDefaultValue(data),
    field: {
      label: data.label,
      fieldname: data.value,
      fieldtype: data.fieldtype,
      options: data.options,
    },
  });
  apply();
}

function removeFilter(index) {
  filters.value.delete(Array.from(filters.value)[index]);
  apply();
}

function clearfilter(close) {
  filters.value.clear();
  apply();
  close && close();
}

function updateValue(value, filter) {
  if (value && typeof value === "object" && !value.target && "value" in value) {
    value = value.value;
  }
  value = value.target ? value.target.value : value;
  if (filter.operator === "in" || filter.operator === "not in") {
    filter.value = value.split(",").map((v) => v.trim());
  } else if (filter.operator === "between") {
    filter.value = [value.split(",")[0], value.split(",")[1]];
  } else {
    filter.value = value;
  }
  debouncedApply();
}

function updateOperator(event, filter) {
  let oldOperatorValue = event.target._value;
  let newOperatorValue = event.target.value;
  filter.operator = event.target.value;
  if (!isSameTypeOperator(oldOperatorValue, newOperatorValue)) {
    filter.value = getDefaultValue(filter.field);
  }
  if (newOperatorValue === "is" || newOperatorValue === "is not") {
    filter.value = "set";
  }
  apply();
}

function isSameTypeOperator(oldOperator, newOperator) {
  let textOperators = [
    "equals",
    "not equals",
    "in",
    "not in",
    ">",
    "<",
    ">=",
    "<=",
  ];
  if (
    textOperators.includes(oldOperator) &&
    textOperators.includes(newOperator)
  )
    return true;
  return false;
}

function apply() {
  const _filters = [];
  filters.value.forEach((f) => {
    _filters.push({
      fieldname: f.fieldname,
      operator: f.operator,
      value: f.value,
      toBoolean: f.field.fieldtype === "Check",
    });
  });
  listViewActions.applyFilters(parseFilters(_filters));
}

function parseFilters(filters) {
  return filters.map(transformIn).reduce((p, c) => {
    if (["equals", "="].includes(c.operator)) {
      if (c.toBoolean) {
        p[c.fieldname] =
          c.value === "Yes" ? true : c.value === "No" ? false : c.value;
      } else {
        p[c.fieldname] = c.value;
      }
    } else {
      p[c.fieldname] = [operatorMap[c.operator.toLowerCase()], c.value];
    }
    return p;
  }, {});
}

function transformIn(f) {
  if (f.operator.includes("like") && !f.value.includes("%")) {
    f.value = `%${f.value}%`;
  }
  return f;
}

const operatorMap = {
  is: "is",
  "is not": "is not",
  in: "in",
  "not in": "not in",
  equals: "=",
  "not equals": "!=",
  yes: true,
  no: false,
  like: "LIKE",
  "not like": "NOT LIKE",
  ">": ">",
  "<": "<",
  ">=": ">=",
  "<=": "<=",
  between: "between",
  timespan: "timespan",
};

const oppositeOperatorMap = {
  is: "is",
  "=": "equals",
  "!=": "not equals",
  equals: "equals",
  "is not": "is not",
  true: "yes",
  false: "no",
  LIKE: "like",
  "NOT LIKE": "not like",
  in: "in",
  "not in": "not in",
  ">": ">",
  "<": "<",
  ">=": ">=",
  "<=": "<=",
  between: "between",
  timespan: "timespan",
};

//// Neoffice — labels wrapped in __(): upstream showed every timespan option in
//// English on non-English sites (the 7 "N Days" entries upstream added are wrapped too).
const timespanOptions = [
  { label: __("Last 7 Days"), value: "last 7 days" },
  { label: __("Last 14 Days"), value: "last 14 days" },
  { label: __("Last 30 Days"), value: "last 30 days" },
  { label: __("Last 90 Days"), value: "last 90 days" },

  //// Neoffice — labels wrapped in __(), as above.
  { label: __("Last Week"), value: "last week" },
  { label: __("Last Month"), value: "last month" },
  { label: __("Last Quarter"), value: "last quarter" },
  { label: __("Last 6 Months"), value: "last 6 months" },
  { label: __("Last Year"), value: "last year" },

  //// Neoffice — labels wrapped in __(), as above.
  { label: __("Yesterday"), value: "yesterday" },
  { label: __("Today"), value: "today" },
  { label: __("Tomorrow"), value: "tomorrow" },

  //// Neoffice — labels wrapped in __(), as above.
  { label: __("This Week"), value: "this week" },
  { label: __("This Month"), value: "this month" },
  { label: __("This Quarter"), value: "this quarter" },
  { label: __("This Year"), value: "this year" },

  //// Neoffice — labels wrapped in __(), as above.
  { label: __("Next 7 Days"), value: "next 7 days" },
  { label: __("Next 14 Days"), value: "next 14 days" },
  { label: __("Next 30 Days"), value: "next 30 days" },

  //// Neoffice — labels wrapped in __(), as above.
  { label: __("Next Week"), value: "next week" },
  { label: __("Next Month"), value: "next month" },
  { label: __("Next Quarter"), value: "next quarter" },
  { label: __("Next 6 Months"), value: "next 6 months" },
  { label: __("Next Year"), value: "next year" },
];

const debouncedApply = useDebounceFn(() => {
  apply();
}, 500);
</script>
<style>
& #operator button,
& #value button {
  width: 100%;
}
</style>
